NDER LINE CHAR;STA $CD0,X;CPX #10BCS QUINC1;STA $EDB,X;QUINC1;DEXBPL QUINCY;LDX #5;QUINC3;LDA SCOREP,XSTA $D29,X;LDA #$52STA $929,X;DEXBPL QUINC3;RTS;;----------;TEXT;.BYTE 8,3,$77,68,92,90,76,98,64,102,104,86,64,102,80,92,90,100,40,0.BYTE 8,4,$67,69,93,91,77,99,65,103,105,87,65,103,81,93,91,101,41,0;; 'CONGRATULATIONS';.BYTE 3,7,$73,25,15,21,18,32,19,3,15,18,5,32,15,6,32,48,48,48,48,48,48.BYTE 32,9,19,32,9,14,0;; 'YOUR SCORE OF 000000 IS IN';.BYTE 10,9,$73,102,78,72,32,102,92,94,32,74,80,106,72,0.BYTE 10,10,$63,103,79,73,32,103,93,95,32,75,81,107,73,0;; 'THE TOP FIVE';.BYTE 5,13,$72,94,86,72,64,100,72,32,72,90,102,72,98,32.BYTE 112,92,104,98,32,90,64,88,72,0.BYTE 5,14,$62,95,87,73,65,101,73,32,73,91,103,73,99,32.BYTE 113,93,105,99,32,91,65,89,73,0;;  'PLEASE ENTER YOUR NAME';.BYTE $FF;;;;;.END